content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5px;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.content {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.chart-card,
.table-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.chart-card h2,
.table-card h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--text-main);
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  margin-top: 0.5rem;
}

.sales-table th,
.sales-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.sales-table th {
  background-color: #f1f5f9;
  font-weight: 600;
  color: var(--text-main);
}

.sales-table tr:hover {
  background-color: #f8fafc;
}

.input-field {
  width: 100%;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 1rem;
  color: var(--text-main);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-field:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.6rem 1.2rem;
  background-color: var(--primary-color);
  color: white;
  font-weight: 600;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.btn:active {
  transform: scale(0.98);
}

@media (min-width: 768px) {
  .app-container {
    padding: 3rem 2rem;
  }
}

import { useState } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface SalesItem {
  month: string;
  sales: number;
}

const initialData: SalesItem[] = [
  { month: '1月', sales: 120 },
  { month: '2月', sales: 150 },
  { month: '3月', sales: 200 },
  { month: '4月', sales: 180 },
  { month: '5月', sales: 220 },
  { month: '6月', sales: 250 },
  { month: '7月', sales: 300 },
  { month: '8月', sales: 280 },
  { month: '9月', sales: 240 },
  { month: '10月', sales: 210 },
  { month: '11月', sales: 260 },
  { month: '12月', sales: 320 },
];

export default function App() {
  const [data, setData] = useState<SalesItem[]>(initialData);

  const handleSalesChange = (index: number, value: string) => {
    const num = parseInt(value, 10);
    const newSales = isNaN(num) ? 0 : num;
    const updated = [...data];
    updated[index] = { ...updated[index], sales: newSales };
    setData(updated);
  };

  const handleReset = () => {
    setData(initialData);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">売上データ管理アプリ</h1>
        <p className="subtitle">1月〜12月の売上実績の確認と編集を行います</p>
      </header>

      <div className="content">
        <div className="chart-card">
          <h2>売上推移グラフ</h2>
          <div style={{ width: '100%', height: 350 }}>
            <ResponsiveContainer>
              <BarChart data={data} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="month" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="sales" fill="var(--primary-color)" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="table-card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h2>月別売上データ編集</h2>
            <button className="btn" onClick={handleReset}>初期値に戻す</button>
          </div>
          <div style={{ overflowX: 'auto' }}>
            <table className="sales-table">
              <thead>
                <tr>
                  <th>月</th>
                  <th>売上 (万円)</th>
                </tr>
              </thead>
              <tbody>
                {data.map((item, index) => (
                  <tr key={item.month}>
                    <td>{item.month}</td>
                    <td>
                      <input
                        type="number"
                        className="input-field"
                        value={item.sales}
                        onChange={(e) => handleSalesChange(index, e.target.value)}
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
